#include <omp.h>
#include <vector>
#include <string>
#include <cstddef>

struct Book {
    std::string title;
    int pages;
};

size_t findLastShortBook(std::vector<Book> const& books) {
    if (books.empty()) return static_cast<size_t>(-1);

    const std::size_t n = books.size();
    std::size_t best = static_cast<std::size_t>(-1);

#pragma omp parallel
    {
        std::size_t local_best = static_cast<std::size_t>(-1);

#pragma omp for nowait
        for (std::size_t i = 0; i < n; ++i) {
            if (books[i].pages < 100) {
                if (local_best == static_cast<std::size_t>(-1) || i > local_best) {
                    local_best = i;
                }
            }
        }

#pragma omp critical
        {
            if (local_best != static_cast<std::size_t>(-1)) {
                if (best == static_cast<std::size_t>(-1) || local_best > best) {
                    best = local_best;
                }
            }
        }
    }

    return best;
}
